If this issue still buggin anyone, i found quick solution (not the best) but worked for me. using @ghost code snippet by importing QueryDeepPartialEntity type directly and using type assertion for the returned instances from create method, ts not complaining now.

```
import { DeepPartial, Repository, } from "typeorm"
import { DefaultOptions } from "./options.interface"
import { QueryDeepPartialEntity } from 'typeorm/query-builder/QueryPartialEntity';

export abstract class AbstractService<TEntity> {
    constructor(
        private readonly repository: Repository<TEntity>,
    ) { }

    async createMany(payload: DeepPartial<TEntity>[], options?: DefaultOptions): Promise<QueryDeepPartialEntity<TEntity>[]> {
        const records = this.repository.create(payload) as QueryDeepPartialEntity<TEntity>[]
        await this.repository.insert(records);
        return records;
    }
}
```
